 CREATE OR REPLACE FUNCTION public.intakedecisionappealcins(i_evalutionid uuid, i_secid character varying)                                                                                                                                                                                                                                                                                             
  RETURNS TABLE(currentdate character varying, youthname character varying, youthid character varying, complaint_id character varying, parentname character varying, parentaddress character varying, complaintdate character varying, offensename character varying[], offensedate character varying, reviewcomments character varying, officername character varying, officerphone character varying)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                     
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                       
 declare P_ID UUID;                                                                                                                                                                                                                                                                                                                                                                                  
    BEGIN                                                                                                                                                                                                                                                                                                                                                                                            
             select p.personid into P_ID                                                                                                                                                                                                                                                                                                                                                             
            from intakeservicerequestevaluation inve                                                                                                                                                                                                                                                                                                                                                 
              join intakeservicerequest INTSR on INTSR.intakenumber=inve.intakenumber and INTSR.activeflag=1                                                                                                                                                                                                                                                                                         
              join intakeservicerequestactor INSRA on INSRA.intakeserviceid=INTSR.intakeserviceid and INSRA.activeflag=1                                                                                                                                                                                                                                                                             
              join actor ACC on ACC.actorid=INSRA.actorid and ACC.activeflag=1 and ACC.actortype='Youth'                                                                                                                                                                                                                                                                                             
              join person p on ACC.personid=p.personid and p.activeflag=1                                                                                                                                                                                                                                                                                                                            
              where  inve.intakeservicerequestevaluationid = i_evalutionid ;                                                                                                                                                                                                                                                                                                                         
         RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                
           (select CAST(to_char(now(),'MM/DD/YYYY') as character varying) as currentdate,                                                                                                                                                                                                                                                                                                            
           cast(p.firstname ||' '|| p.lastname as character varying) as youthname,                                                                                                                                                                                                                                                                                                                   
           cast (p.cjamspid as character varying)as youthid,                                                                                                                                                                                                                                                                                                                                         
        complaintid as complaint_id,                                                                                                                                                                                                                                                                                                                                                                 
        CAST(coalesce(mother.mother_name,father.father_name,guardian.guardian_name) as character varying) as parentname,                                                                                                                                                                                                                                                                             
        CAST(coalesce(mother.mother_address,father.father_address,guardian.guardian_address) as character varying) as parentaddress,                                                                                                                                                                                                                                                                 
        cast (to_char(complaintreceiveddate,'MM/DD/YYYY') as character varying) as complaintdate,                                                                                                                                                                                                                                                                                                    
        (select array_agg(AG.name)  from  allegation AG                                                                                                                                                                                                                                                                                                                                              
         join intakeservicerequestevaluationconfig ITSEC  on ITSEC.allegationid=AG.allegationid and AG.activeflag=1                                                                                                                                                                                                                                                                                  
         where  ITSEC.intakeservicerequestevaluationid=inve.intakeservicerequestevaluationid and ITSEC.activeflag=1 )as offensename,                                                                                                                                                                                                                                                                 
       cast (case                                                                                                                                                                                                                                                                                                                                                                                    
             when inve.unknownrange=0 then to_char(inve.offensedate,'MM/DD/YYYY')                                                                                                                                                                                                                                                                                                                    
             when inve.unknownrange=1 then to_char(inve.offensedate,'MM/DD/YYYY')                                                                                                                                                                                                                                                                                                                    
             when inve.unknownrange=2 then to_char(inve.begindate,'MM/DD/YYYY')|| ' - ' || to_char(inve.enddate,'MM/DD/YYYY')                                                                                                                                                                                                                                                                        
        end as character varying) as offensedate,                                                                                                                                                                                                                                                                                                                                                    
        cast (itsdc.reviewcomments as character varying) as reviewcomments,                                                                                                                                                                                                                                                                                                                          
        (select distinct up.fullname from userprofile up where securityusersid = i_secid) as officername,                                                                                                                                                                                                                                                                                            
             (select distinct phonenumber from userprofilephonenumber where securityusersid = i_secid) as officerphone                                                                                                                                                                                                                                                                               
        from intakeservicerequestevaluation inve                                                                                                                                                                                                                                                                                                                                                     
        join intakeservicerequest ins on ins.intakenumber=inve.intakenumber                                                                                                                                                                                                                                                                                                                          
        left join intakeservicerequestdispositioncode itsdc on ins.intakeserviceid =itsdc.intakeserviceid and itsdc.activeflag=1                                                                                                                                                                                                                                                                     
        left join intakeservicerequestactor INSRA on INSRA.intakeserviceid=ins.intakeserviceid and INSRA.activeflag=1                                                                                                                                                                                                                                                                                
                 left join actor ACC on ACC.actorid=INSRA.actorid and ACC.activeflag=1 and ACC.actortype='Youth'                                                                                                                                                                                                                                                                                     
                 join person p on ACC.personid=p.personid and p.activeflag=1                                                                                                                                                                                                                                                                                                                         
                 left join personaddress pa on p.personid = pa.personid and pa.activeflag=1                                                                                                                                                                                                                                                                                                          
                 left join personrelation pr on p.personid = pr.personid and pr.activeflag=1                                                                                                                                                                                                                                                                                                         
        join intakeservicerequestevaluationconfig ITSEC on ITSEC.intakeservicerequestevaluationid=inve.intakeservicerequestevaluationid and ITSEC.activeflag=1                                                                                                                                                                                                                                       
        join allegation AG on ITSEC.allegationid=AG.allegationid and AG.activeflag=1                                                                                                                                                                                                                                                                                                                 
        left join (select m.pid as mother_pid,firstname||','||lastname as mother_name,personaddress.address||','||personaddress.zipcode||','||personaddress.city||','||personaddress.state||','||personaddress.country as mother_address,personphonenumber.phonenumber as mother_phone                                                                                                               
                         from  person                                                                                                                                                                                                                                                                                                                                                                
                         left join personaddress on person.personid=personaddress.personid and personaddress.activeflag=1                                                                                                                                                                                                                                                                            
                         left join personphonenumber on person.personid=personphonenumber.personid and personphonenumber.activeflag=1                                                                                                                                                                                                                                                                
                         join (select a.personid as pid,a.actorid as prid                                                                                                                                                                                                                                                                                                                            
                               from actor a join intakeservicerequestactor insa                                                                                                                                                                                                                                                                                                                      
                               on a.actorid=insa.actorid and insa.activeflag=1                                                                                                                                                                                                                                                                                                                       
                               join actorrelationship ar on ar.intakeservicerequestactorid=insa.intakeservicerequestactorid and ar.activeflag=1                                                                                                                                                                                                                                                      
                               where  ar.relationshiptypekey='mother' and a.personid=P_ID) m                                                                                                                                                                                                                                                                                                         
                         on person.personid=m.prid                                                                                                                                                                                                                                                                                                                                                   
                         ) mother                                                                                                                                                                                                                                                                                                                                                                    
                         on p.personid=mother.mother_pid                                                                                                                                                                                                                                                                                                                                             
              left join (select  f.pid as father_pid ,firstname||','||lastname as father_name,personaddress.address||','||personaddress.zipcode||','||personaddress.city||','||personaddress.state||','||personaddress.country as father_address,personphonenumber.phonenumber as father_phone                                                                                                       
                         from  person                                                                                                                                                                                                                                                                                                                                                                
                         left join personaddress on person.personid=personaddress.personid and personaddress.activeflag=1                                                                                                                                                                                                                                                                            
                         left join personphonenumber on person.personid=personphonenumber.personid and personphonenumber.activeflag=1                                                                                                                                                                                                                                                                
                         join (select a.personid as pid,a.actorid as prid                                                                                                                                                                                                                                                                                                                            
                               from actor a join intakeservicerequestactor insa                                                                                                                                                                                                                                                                                                                      
                               on a.actorid=insa.actorid and insa.activeflag=1                                                                                                                                                                                                                                                                                                                       
                               join actorrelationship ar on ar.intakeservicerequestactorid=insa.intakeservicerequestactorid and ar.activeflag=1                                                                                                                                                                                                                                                      
                               where  ar.relationshiptypekey='father' and a.personid=P_ID) f                                                                                                                                                                                                                                                                                                         
                        on person.personid=f.prid) father                                                                                                                                                                                                                                                                                                                                            
                        on  p.personid=father.father_pid                                                                                                                                                                                                                                                                                                                                             
               left join (select  g.pid as guardian_pid ,firstname||','||lastname as guardian_name,personaddress.address||','||personaddress.zipcode||','||personaddress.city||','||personaddress.state||','||personaddress.country as guardian_address,personphonenumber.phonenumber as guardian_phone                                                                                              
                         from  person                                                                                                                                                                                                                                                                                                                                                                
                         left join personaddress on person.personid=personaddress.personid and personaddress.activeflag=1                                                                                                                                                                                                                                                                            
                         left join personphonenumber on person.personid=personphonenumber.personid and personphonenumber.activeflag=1                                                                                                                                                                                                                                                                
                         join (select a.personid as pid,a.actorid as prid                                                                                                                                                                                                                                                                                                                            
                               from actor a join intakeservicerequestactor insa                                                                                                                                                                                                                                                                                                                      
                               on a.actorid=insa.actorid and insa.activeflag=1                                                                                                                                                                                                                                                                                                                       
                               join actorrelationship ar on ar.intakeservicerequestactorid=insa.intakeservicerequestactorid and ar.activeflag=1                                                                                                                                                                                                                                                      
                               where  ar.relationshiptypekey='guardian' and a.personid=P_ID) g                                                                                                                                                                                                                                                                                                       
                        on person.personid=g.prid) guardian                                                                                                                                                                                                                                                                                                                                          
                        on  p.personid=guardian.guardian_pid                                                                                                                                                                                                                                                                                                                                         
        where  inve.intakeservicerequestevaluationid = i_evalutionid) ;                                                                                                                                                                                                                                                                                                                              
    end;                                                                                                                                                                                                                                                                                                                                                                                             
   $function$                                                                                                                                                                                                                                                                                                                                                                                          

